/// <summary>
/// Event handler class for <c>PriceDiscAdmTable</c> form
/// </summary>
class UPSPriceDiscAdmTableFormEventHandler
{
}

Method.Source:
/// <summary>
/// Override lookup for journal called from unified pricing service
/// </summary>
/// <param name="_sender">Sender control</param>
/// <param name="_e">Param</param>
[FormControlEventHandler(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_JournalName), FormControlEventType::Lookup)]
public static void PriceDiscAdmTable_JournalName_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    SysTableLookup          sysTableLookup  = SysTableLookup::newParameters(tableNum(PriceDiscAdmName), _sender);
    Query                   query           = new Query();
    QueryBuildDataSource    qbds            = query.addDataSource(tableNum(PriceDiscAdmName));        

    if (_sender.formRun().args().menuItemName() == menuItemDisplayStr(UPSPriceDiscAdmTable_Sales))
    {
        qbds.addRange(fieldNum(PriceDiscAdmName, DefaultRelation)).value(queryValue(PriceType::PriceSales));
        qbds.addRange(fieldNum(PriceDiscAdmName, PriceDiscPriceAttributeEnable)).value(queryValue(NoYes::Yes));
    }
    else
    {
        qbds.addRange(fieldNum(PriceDiscAdmName, PriceDiscPriceAttributeEnable)).value(queryValue(NoYes::No));
    }

    sysTableLookup.addLookupfield(fieldNum(PriceDiscAdmName, JournalName));
    sysTableLookup.addLookupfield(fieldNum(PriceDiscAdmName, Name));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = _e as FormControlCancelableSuperEventArgs;

    ce.CancelSuperCall();
}
